<template><section class="auth-shell"><div class="auth-card"><p class="eyebrow">Новая учётная запись</p><h1>Регистрация</h1><p>Это локальный учебный профиль. Не вводите настоящий пароль.</p><form @submit.prevent="submit"><div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><label>Имя<input v-model.trim="name" required minlength="2" maxlength="80" autocomplete="name" /></label><label>E-mail<input v-model.trim="email" required type="email" autocomplete="email" /></label><label>Пароль<input v-model="password" required minlength="6" maxlength="128" type="password" autocomplete="new-password" /></label><button class="btn btn-clay wide" :disabled="busy">{{ busy ? 'Создаём…' : 'Создать учебный профиль' }}</button></form><p>Уже есть профиль? <RouterLink :to="{name:'login',query:$route.query}">Войти</RouterLink></p></div></section></template><script setup>import { ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { useSession } from '../composables/useSession'; const name=ref(''),email=ref(''),password=ref(''),error=ref(''),busy=ref(false); const route=useRoute(),router=useRouter(),{register}=useSession(); async function submit(){busy.value=true;error.value='';try{await register(name.value,email.value,password.value);router.replace(typeof route.query.next==='string'?route.query.next:'/profile');}catch(e){error.value=e.message;}finally{busy.value=false;}}</script>
